function rolloutGroup(userId, percent) {
  return (userId % 100) < percent ? 'in rollout' : 'waiting';
}
const users = [3, 50, 150];
console.log(users.map(u => rolloutGroup(u, 10)).join(','));

function listingReady(listing) {
  return Boolean(listing.icon) && listing.screenshots >= 2 && listing.description.length > 0;
}
console.log('ready: ' + listingReady({ icon: true, screenshots: 1, description: 'Tasks!' }));

